<?php
require_once __DIR__.'/../config/constants.php';require_admin();if(!is_post())redirect('admin/manage-category.php');verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id)redirect('admin/manage-category.php');$stmt=db()->prepare('SELECT COUNT(*) FROM tbl_food WHERE category_id=?');$stmt->execute([$id]);if((int)$stmt->fetchColumn()>0){flash('error','Cannot delete a category that still contains foods.');redirect('admin/manage-category.php');}$stmt=db()->prepare('SELECT image_name FROM tbl_category WHERE id=?');$stmt->execute([$id]);$image=$stmt->fetchColumn();$stmt=db()->prepare('DELETE FROM tbl_category WHERE id=?');$stmt->execute([$id]);if($image){$p=__DIR__.'/../images/Category/'.basename((string)$image);if(is_file($p))@unlink($p);}flash('success','Category deleted.');redirect('admin/manage-category.php');
